insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (251, 'This Small Blue Dot', 'Sworder, Zeno', NULL, 'A little girl explores all of the funny, strange, and wonderful things that make living on Earth so special in this beautifully illustrated children’s story. With a strong message of hope, interconnectedness, and empowerment, This Small Blue Dot features a little girl explaining the world to her baby sister. She hits on small wonders, big lessons, and everything in between, from sharing the joy of silly dances to contemplating the nature of this “small blue dot” we all live on. Author and illustrator Zeno Sworder, who hails from a multicultural background, wrote this story when his daughter was unable to find picture books with characters who looked like her. His precocious young narrator has opinions on plenty of things: nature and the environment, embracing difference, the power of imagination—and the trouble with broccoli. Rich pencil and crayon illustrations conjure up memories of childhood in this celebration of who we are, where we come from, and where our dreams may take us. In This Small Blue Dot, Sworder captures not only life lessons but also the fun, often strange experience of being a member of the human family on planet Earth.', 'verified', '251_this_small_blue_dot.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (252, 'My Strange Shrinking Parents - A Tall Tale', 'Sworder, Zeno', NULL, 'It goes without saying that all children believe their parents to be strange. Mine were unusual for a different reason…
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (253, 'The Arrival', 'Tan, Shaun', NULL, 'A unique 128-page, textless graphic novel, in black, white and sepia, The Arrival draws its inspiration from tales of migrants in past and recent times. The central character is a middle-aged man who arrives in a strange new place and tries to find a place to live, a job and a handle on a new language. He encounters many challenges, all described entirely through visual sequences. The absence of words emphasises the strangeness of the situation and the loneliness experienced by many migrants, but the ending is full of affirmation and hope, when the wife and son the migrant had to leave behind are finally able to join him in their new homeland. www.thearrival.com.au', 'verified', '253_the_arrival.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (254, 'Under Your Feet - Soil, Sand, and Everything Underground', 'Tang, Wenjia', NULL, 'Down where worms wriggle and microbes squirm, there''s a whole world waiting to be discovered…
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (255, 'Dear Mrs. LaRue - Letters from Obedience School', 'Teague, Mark', NULL, 'A hilarious epistolary story told through letters from a dog at obedience school to his owner, dramatically exaggerating his suffering. This clever narrative demonstrates persuasive writing and unreliable narration through contrasting text and illustrations.', 'needs_review', '255_dear_mrs_larue_letters_from_obedience_school.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (256, 'That Bird Has Arms!', 'Temple, Kate', NULL, 'Roy is an ordinary bird in every way. He is not the biggest, or the smallest. His squawk is not the loudest or the quietest. He even follows the same football team as everyone else. He was very normal except for one thing – he has ARMS. Absolutely nobody knows – and Roy would like to keep it that way... That Bird Has Arms is a story about difference and identity. It’s about learning to see that what sets you apart is what makes you strong, and it’s about pride in your own uniqueness. A 2024 CBCA Picture Book Book of the Year: Shortlisted Book', 'verified', '256_that_bird_has_arms.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (257, 'Fossil', 'Thomson, Bill', NULL, 'When a boy discovers that breaking open rocks with fossils brings the fossils back to life, he ends up bringing something back that is bigger than he can handle.', 'verified', '257_fossil.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (258, 'My Australian Story - Gallipoli', 'Tucker, Alan', NULL, 'A novel about an iconic Australian battle that formed the Anzac legend. Lying about his age, and looking for adventure, 14-year-old Victor March enlists in the 10th Battalion of the AIF to fight in the Great War. Victor and his new mates, Fish, Needle and Robbo, are headed for the Gallipoli peninsula and into battle. He is among the first soldiers to land at Anzac Cove on 25 April 1915, and the world as he knows it is about to change. In his diary, Victor records the horrors of war, his friendships, his fears and the story of Australia''s most legendary military campaign.', 'verified', '258_my_australian_story_gallipoli.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (259, 'My Australian Story - Cyclone Tracy', 'Tucker, Alan', NULL, 'Darwin''s almost completely destroyed; buildings, shops, houses, cars. Whole streets are gone, even the signposts. And now the people are going. Evacuations started today. Ryan just wants to hang out with his mates, go fishing and avoid being hassled by his dad, the super-strict deputy principal. But troubles with his dad are nothing compared with what lies ahead: Cyclone Tracy is about to hit Darwin.', 'verified', '259_my_australian_story_cyclone_tracy.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (260, 'This Book Thinks Ya Deadly! - A Celebration of Blak Excellence', 'Tutt, Corey', NULL, 'This Book Thinks Ya Deadly! is an inspirational, illustrated compendium that celebrates the diversity and success of First Nations People.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (261, 'The First Scientists - Deadly Inventions and Innovations from Australia''s First Peoples', 'Tutt, Corey', NULL, 'The First Scientists is the highly anticipated, illustrated science book from Corey Tutt of DeadlyScience. With kids aged 7 to 12 years in mind, this book will nourish readers'' love of science and develop their respect for Indigenous knowledge at the same time.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (262, 'Jumanji', 'Van Allsburg, Chris', NULL, 'Roll the dice, make your move, and plunge into one of the most imaginative stories of our time! The game under the tree looked like a hundred others Peters and Judy had at home. But they were searching for something interesting to do, so they decided to give Jumanji a try. Little did they know when they unfolded its ordinary-looking playing board that they were about to be launched into the most exciting and bizarre adventure of their lives... This picture book classic from Chris Van Allsburg has been honored with many awards, including the Caldecott Medal. The surreal story also became the basis of multiple blockbuster film adaptations. This story about a game that comes startlingly to life is a family favorite that inspires imagination and explores the ever-shifting line between fantasy and reality.', 'verified', '262_jumanji.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (263, 'Jorn''s Magnificent Imagination', 'Vass, Coral', NULL, 'Celebrating new ideas that can make a world of difference, Jorn''s Magnificent Imagination is the true story of Jorn Utzon, the architect of the world-renowned Sydney Opera House.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (264, 'Alexander and the Terrible, Horrible, No Good, Very Bad Day', 'Viorst, Judith', NULL, 'After more than forty years, still the worst day ever! Now a major film starring Steve Carrell, Jennifer Garner and Bella Thorne. Read the inspiration behind the new major film starring Steve Carrell, Jennifer Garner and Bella Thorne. He could tell it was going to be a terrible, horrible, no good, very bad day... He went to sleep with gum in his mouth and woke up with gum in his hair... When he got out of bed, he tripped over his skateboard and by mistake dropped his sweater in the sink while the water was running... What do you do on a day like that? Well, you may think about going to Australia. You may also be glad to find that some days are like that for other people too. This funny and endearing story has delighted readers for more than forty years and is the inspiration behind the upcoming film, starring Jennifer Garner and Steve Carrell.', 'verified', '264_alexander_and_the_terrible_horrible_no_good_very_bad_day.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (265, 'The Tenth Good Thing About Barney', 'Viorst, Judith', NULL, 'My cat Barney died this Friday. I was very sad. My mother said we could have a funeral for him, and I should think of ten good things about Barney so I could tell them...
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (266, 'Earrings!', 'Viorst, Judith', NULL, 'I want them. I need them. I love them. Beautiful earrings. Glorious earrings. What will a young girl do to get her ears pierced? Will she walk the dog for a year? YES! Will she clean her room every day for a year? YES! Will she be nice to her brother for a year? YES! Well, maybe for six months...', 'verified', '266_earrings.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (267, 'Tamarra - A Story of Termites on Gurindji Country', 'Wadrill, Violet', NULL, 'Tamarra: A Story of Termites on Gurindji Country is a fascinating, illustrated science book that takes kids inside the life of termites through storytelling from the Gurindji People.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (268, 'Why I Love Summer', 'Wagner, Michael', 'Tom Jellett', 'There are four seasons in a year, and they''re all awesome, but only one of them gets to be summer!
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (269, 'Dirt by Sea', 'Wagner, Michael', NULL, 'Daisy lives in inland Australia with her dad and her grandparents, loving the red dirt land around her. But when her dad realises she''s never seen the beach, they set off on a trip you won''t want to miss. A once-in-a-lifetime father-daughter trip along the Australian coast that was inspired by the first holiday Daisy''s dad took with her mum. With a journey map in the endpapers, you or your young ones could even start planning your own Aussie adventure.. For Little Adventurers- What They Will Learn * An appreciation for the diverse Australian landscape * The value of quality family time * The joy of discovering new places * Emotional growth through a gentle exploration of loss A Keepsake for All Seasons Dive into a modern classic with this visually captivating picture book, featuring 40 pages of extraordinary comic-style illustrations. This visual feast perfectly complements the heartwarming, uniquely Australian narrative, engaging both kids and adults. Ideal for young minds from early childhood to middle primary, it offers an emotionally rich story that nurtures growth. This picture book is a perfect keepsake, equally delightful under a Christmas tree or as a summer day companion, making it a treasured addition to any collection. ----------------------------- "Vibrant and engaging... " BOOKSELLER AND PUBLISHER "Destined to become a classic." GLAMADELAIDE "A most appealing graphic novel in picture book form..." PAPERBARK WORDS "An entertaining story with thoughtfulness, depth, and lots of fun to be had." MAGPIES "Engaging dialogues and witty illustrations..." INTERNATIONAL YOUTH LIBRARY "A book that will bear repeated readings." READPLUS "It''s the new Possum Magic or Wombat Stew." ONE MORE PAGE', 'verified', '269_dirt_by_sea.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (270, 'Fing - An Explosively Funny Tale', 'Walliams, David', NULL, 'The jaw-achingly funny children''s book from No. 1 bestselling author David Walliams - a deliciously daft Tall Story of a child who had everything, but still wanted more. Illustrated by artistic genius, Tony Ross.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (272, 'Snap!', 'Walker, Anna', NULL, 'A brilliant onomatopoeic text accompanies the iconic illustrations of Anna Walker in this hilarious and utterly adorable frog adventure. How will Frog escape the swoops, snips, and snaps of all sorts of animals in the forest and get to the party on time? This is a delightful, gripping, and funny adventure narrative aimed at very young readers, that will no doubt appeal to older children and adults alike.', 'verified', '272_snap.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (273, 'Mr Huff', 'Walker, Anna', 'Anna Walker', 'Award-winning and much-loved author and illustrator Anna Walker gives us a gentle, poignant, affirming and wise picture book sure to delight all ages. Mr. Huff is a story about the clouds and the sunshine in each of our lives. Bill is having a bad day. Mr Huff is following him around and making everything seem difficult. Bill tries to get rid of him, but Mr Huff just gets bigger and bigger! Then they both stop, and a surprising thing happens . . .', 'verified', '273_mr_huff.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (274, 'Lottie and Walter', 'Walker, Anna', NULL, 'Lottie secretly knows there is a shark in the pool waiting to eat her, until her new walrus friend, Walter, helps her to conquer her fear.', 'verified', '274_lottie_and_walter.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (275, 'Luke''s Way of Looking', 'Wheatley, Nadia', 'Matt Ottley', 'All the boys in Luke''s art class see things the same way -- except for Luke. Luke has his own vision of the world, a wild, colorful, crazy vision that upsets his art teacher ("he went ballistic") and confuses the other boys. When he just can''t face one more difficult day at school, Luke discovers a whole "palace" filled with wild, colorful, crazy pieces of art.', 'verified', '275_lukes_way_of_looking.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (276, 'Papunya School Book of Country and History', 'Wheatley, Nadia', NULL, 'Multi-award-winning, The Papunya School Book of Country and History is a unique and fascinating account of the history of Western Desert communities from an Indigenous perspective.', 'verified', '276_papunya_school_book_of_country_and_history.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (277, 'Charlotte''s Web', 'White, E.B.', NULL, 'This beloved book by E. B. White, author of Stuart Little and The Trumpet of the Swan, is a classic of children''s literature that is "just about perfect." This high-quality paperback features vibrant illustrations colorized by Rosemary Wells!Some Pig. Humble. Radiant. These are the words in Charlotte''s Web, high up in Zuckerman''s barn. Charlotte''s spiderweb tells of her feelings for a little pig named Wilbur, who simply wants a friend. They also express the love of a girl named Fern, who saved Wilbur''s life when he was born the runt of his litter.E. B. White''s Newbery Honor Book is a tender novel of friendship, love, life, and death that will continue to be enjoyed by generations to come. This edition contains newly color illustrations by Garth Williams, the acclaimed illustrator of E. B. White''s Stuart Little and Laura Ingalls Wilder''s Little House series, among many other books.', 'verified', '277_charlottes_web.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (278, 'The Firefighters', 'Whiting, Sue', 'Donna Rawlins', 'From sounding the siren to speeding off in their fire engine (empty boxes will do), children love playing firefighters with Mrs. Iverson. This winsome firefighting tale is full of sound words and bright, full-color illustrations.', 'verified', '278_the_firefighters.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (279, 'The Echidna Near My Place', 'Whiting, Sue', NULL, 'A delightful addition to the Nature Storybooks series, The Echidna Near My Place tells the story of a child and their nana, and the echidna they love to follow around - now in paperback. Nana and I walk through the paddock most days. And you know what? An echidna lives here. We don''t always see it. But I''m always looking for it. As a young child and their nana go for walks together, they follow a short-beaked echidna keenly observing and discussing what its life might be like. Learn with them about what echidnas eat, where they live, and how they protect themselves. A wonderful addition to the acclaimed and award-winning Nature Storybook series, which provides memorable reading experiences, combining narrative and factual forms.', 'verified', '279_the_echidna_near_my_place.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (280, 'The Book of Chance', 'Whiting, Sue', NULL, 'Chance is a black-and-white thinker until she realises that sometimes there are shades of grey. Chance is in Year 7 and thinks she has it all - a loving mother, dog Tiges, best friend and almost-sister next door. But when a reality TV team makes over her house, she discovers newspaper cuttings from the past that cause her to question the world as she knows it and everyone in it. Then she finds herself caught between two realities, identities and worlds. Face-to-face with the truth, Chance has a very difficult decision to make, which almost splits her in two. This powerful story explores what is true and what is fake in today''s world. And while Chance is all about the truth, she ponders whether "Maybe being truthful was really just a big lie."', 'verified', '280_the_book_of_chance.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (281, 'Flotsam', 'Wiesner, David', NULL, 'A highly acclaimed, wordless Caldecott Award-winning picture book from the only living three-time winner of the Caldecott Medal: David Wiesner. A bright, science-minded boy goes to the beach equipped to collect and examine flotsam-anything floating that has been washed ashore. Bottles, lost toys, small objects of every description are among his usual finds. But there''s no way he could have prepared for one particular discovery: a barnacle-encrusted underwater camera, with its own secrets to share . . . and to keep. ''Beautiful child’s graphic novel... Wiesner keeps his viewpoint strictly childlike, magnifying the mundane until you see his world in a grain of sand.'' EVENING STANDARD ''Beautiful'' TELEGRAPH ''Wonderfully imaginative . . . The pictures are packed with details and each re-reading provides more joy'' BOOKSELLER ''From arguably the most inventive and cerebral visual storyteller in children''s literature comes a wordless invitation . . . not to be resisted'' KIRKUS REVIEWS, starred review', 'verified', '281_flotsam.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (282, 'The Treasure Box', 'Wild, Margaret', 'Freya Blackwood', 'From two of our most talented picture-book creators comes this celebration of things that can''t be destroyed by bombs or fire. A haunting and beautiful tale of the power of words, the importance of stories and the resilience of the human spirit. As war rages, Peter and his father flee their home, taking with them a treasure box that holds something more precious than jewels. They journey through mud and rain and long cold nights, and soon their survival becomes more important than any possessions they carry. But as the years go by, Peter never forgets the treasure box, and one day he returns to find it...', 'verified', '282_the_treasure_box.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (283, 'The Sloth Who Came to Stay', 'Wild, Margaret', 'Vivienne To', 'This wryly amusing story is about a fast family who are taught to slow down when an adorable sloth comes to stay is by the award-winning author of Fox and This Little Piggy Went Dancing.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (285, 'That is Not a Good Idea!', 'Willems, Mo', NULL, 'That Is Not a Good Idea! is a hilarious, interactive picture book from bestselling author and illustrator Mo Willems, the creator of books like Don’t Let the Pigeon Drive the Bus, the Knuffle Bunny series, the Elephant and Piggie series, Goldilocks and the Three Dinosaurs, and many other new classics. Inspired by the evil villains and innocent damsels of silent movies, Willems tells the tale of a hungry fox who invites a plump goose to dinner. As with the beloved Pigeon books, kids will be calling out the signature refrain and begging for repeated readings. The funny details in the full-color illustrations by three-time Caldecott Honoree Mo Willems will bring nonstop laughter to story time.', 'verified', '285_that_is_not_a_good_idea.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (286, 'Knuffle Bunny Too: A Case of Mistaken Identity', 'Willems, Mo', NULL, 'The hilarious second instalment in the Knuffle Bunny trilogy from bestselling, award-winning author Mo Willems.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (287, 'Knuffle Bunny', 'Willems, Mo', NULL, 'Merging expressive cartoon network-esque illustrations with beautiful black and white photographs of Brooklyn, this funny story tells how Trixie and Knuffel Bunny''s trip to the laundromat with Dad goes terribly wrong when Trixie realizes some bunny''s been left behind...! Her attempts to alert Dad all the way home are unsuccessful, until Mum points out that Knuffel Bunny is missing and the family hotfoot it back to the laundromat. Fortunately, KB is safe, if a little wet...', 'verified', '287_knuffle_bunny.jpg');
